      const v = parseFloat(el.value);
      cb(v);
      label.textContent = fmt ? fmt(v) : v;
    };
    el.addEventListener('"'input', update);
    update();
  };

  bind('count', 'v-count', v => { COUNT = Math.round(v); resetParticles(); }, v => v.toLocaleString());
  bind('speed', 'v-speed', v => { SPEED = v; }, v => v.toFixed(1));
  bind('life', 'v-life', v => { LIFE = v; }, v => v);
  bind('detail', 'v-detail', v => { DETAIL = v; }, v => v);

  document.querySelectorAll('#palette button').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#palette button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      palette = btn.dataset.p;
    });
  });

  "'$('"'colorA').addEventListener('input', e => { colors[0] = e.target.value; if (palette === 'custom') {} });
  "'$('"'colorB').addEventListener('input', e => { colors[1] = e.target.value; });
  "'$('"'reset').addEventListener('click', () => {
