    mono:     ['#f4f6fb', '#aab3c2', '#55606f', '#ffffff', '#cfd6e3'],
    custom:   null,
  };

  function fieldAngle(x, y) {
    const t = performance.now() * 0.00012;
    const n = noiseWorld(x * 0.9, y * 0.9);
    let angle = n * Math.PI * (2 + DETAIL * 0.4) + t * (0.3 + DETAIL * 0.05);
    if (mouse.active) {
      const dx = x - mouse.x, dy = y - mouse.y;
      const d2 = dx*dx + dy*dy;
      if (d2 < 220 * 220) {
        const swirl = Math.atan2(dy, dx) + Math.PI * 0.5;
        const strength = (1 - Math.sqrt(d2) / 220) * 1.6;
        angle = lerp(angle, swirl, strength);
      }
    }
    return angle;
  }

  function makeParticle() {
    return {
      x: Math.random() * W,
      y: Math.random() * H,
      age: 0,
    };
  }

  function resetParticles() {
    particles = new Array(COUNT);
    for (let i = 0; i < COUNT; i++) particles[i] = makeParticle();
  }

  // ------------------------------------------------------------------ engine
  function step() {
    // fade previous frame so trails accumulate
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = 'rgba(11,14,20,0.28)';
    ctx.fillRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'lighter';

    const speed = SPEED;
    const lifeFrames = LIFE * 60;

    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];
      const angle = fieldAngle(p.x, p.y);
      const vx = Math.cos(angle) * speed;
      const vy = Math.sin(angle) * speed;
      p.x += vx;
      p.y += vy;
      p.age++;

      if (p.x < 0 || p.x > W || p.y < 0 || p.y > H || p.age > lifeFrames) {
        particles[i] = makeParticle();
        continue;
      }

      const t = noiseWorld(p.x * 0.5, p.y * 0.5);
      ctx.strokeStyle = computeColor(t);
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.moveTo(p.x - vx, p.y - vy);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();

      if (mouse.active && (i % 200 === 0)) {
        ctx.fillStyle = 'rgba(255,255,255,0.5)';
        ctx.beginPath();
        ctx.arc(mouse.x, mouse.y, 120, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.25)';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    }
    ctx.globalCompositeOperation = 'source-over';
  }

  function computeColor(t) {
    if (palette === 'mono') {
      const c = 180 - Math.floor(t * 140);
      return "'`rgba(${c},${c+5},${c+18},0.55)`;
    }
    const pal = PALETTES[palette] || colors;
    const idx = t * (pal.length - 1);
    const i = Math.min(pal.length - 2, Math.floor(idx));
    const f = idx - i;
    const a = hexToRgb(pal[i]), b = hexToRgb(pal[i + 1]);
    const r = Math.round(lerp(a[0], b[0], f));
    const g = Math.round(lerp(a[1], b[1], f));
    const bl = Math.round(lerp(a[2], b[2], f));
    return `rgba(${r},${g},${bl},0.5)`;
  }

  function hexToRgb(hex) {
    const v = parseInt(hex.slice(1), 16);
    return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
  }

  // ------------------------------------------------------------------ loop
  function loop(ts) {
    step();
    const fpsNow = 1000 / Math.max(1, ts - lastFrame);
    fps = lerp(fps, fpsNow, 0.1);
    lastFrame = ts;
    updateStats();
    requestAnimationFrame(loop);
  }

  // ------------------------------------------------------------------ UI
  const $ = id => document.getElementById(id);
  let statTimer = 0;

  function updateStats() {
    statTimer++;
    if (statTimer % 30 !== 0) return;
    $('"'stats').textContent = "'`fps ${fps.toFixed(0)} · ${particles.length.toLocaleString()} particles`;
  }

  const bind = (id, valueId, cb, fmt) => {
    const el = $(id);
    const label = $(valueId);
    const update = () => {
      const v = parseFloat(el.value);
      cb(v);
      label.textContent = fmt ? fmt(v) : v;
    };
    el.addEventListener('"'input', update);
    update();
  };

  bind('count', 'v-count', v => { COUNT = Math.round(v); resetParticles(); }, v => v.toLocaleString());
  bind('speed', 'v-speed', v => { SPEED = v; }, v => v.toFixed(1));
  bind('life', 'v-life', v => { LIFE = v; }, v => v);
  bind('detail', 'v-detail', v => { DETAIL = v; }, v => v);

  document.querySelectorAll('#palette button').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#palette button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      palette = btn.dataset.p;
    });
  });

  "'$('"'colorA').addEventListener('input', e => { colors[0] = e.target.value; if (palette === 'custom') {} });
  "'$('"'colorB').addEventListener('input', e => { colors[1] = e.target.value; });
  "'$('"'reset').addEventListener('click', () => {
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#0b0e14';
    ctx.fillRect(0, 0, W, H);
    resetParticles();
  });

  canvas.addEventListener('mousemove', e => {
    mouse.x = e.clientX; mouse.y = e.clientY; mouse.active = true;
  });
  canvas.addEventListener('mouseleave', () => { mouse.active = false; });
  canvas.addEventListener('click', () => {
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = 'rgba(11,14,20,0.85)';
    ctx.fillRect(0, 0, W, H);
  });
  window.addEventListener('blur', () => { mouse.active = false; });

  // ------------------------------------------------------------------ init
  resize();
  resetParticles();
  ctx.fillStyle = '#0b0e14';
  ctx.fillRect(0, 0, W, H);
  requestAnimationFrame(loop);
})();
